import{_ as e,o,c as r,a4 as a}from"./chunks/framework.2-Vke5-n.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"帳票<wbr>利用ガイドライン","tagline":"Report Usage Guidelines","actions":[{"theme":"brand","text":"帳票利用ガイドライン","link":"./report_guidelines.md"}]}},"headers":[],"relativePath":"documents/forReport/index.md","filePath":"documents/forReport/index.md"}'),i={name:"documents/forReport/index.md"};function n(l,t,s,d,p,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>帳票とは企業の経営活動に関わる書類で、<strong>帳簿</strong>と<strong>伝票</strong>の総称を指す。帳票の起源は古く、人類が経済活動の中で契約が発生した瞬間から合意内容を残すために存在したと考えられる。媒体は粘土板、紙、PDFなどの電子データに変化したが、本質的な役割は変わっていない。</p><ul><li><strong>記録と合意形成:</strong> ある時点の受注、請求、納品などの取引状態を記録し、契約者間の合意形成の証とする</li><li><strong>法的・税務への対応:</strong> 監査や税務処理において、ビジネス活動の正当性を証明する正データとなる</li></ul><p>昨今のIT/DX化でペーパーレスがなされ、紙の帳票は減っているが、電子帳簿保存法やインボイス対応などで、帳票自体の重要性は以前と変わらない。帳票を学ぶことは、単なる出力機能の実装に留まらず、ITコンサルタントとして必要な次のスキルを得ることができる。</p><ol><li><strong>業務知識</strong>: 優れた帳票は、ビジネスの本質的なデータ構造を映し出す。帳票を設計することは、業務フローとデータモデルの不整合を発見し、良いドメインモデルを見つけることに繋がる</li><li><strong>利用者視点の獲得</strong>: 帳票はエンドユーザーが見るために生成するため、システム全体のUI/UXに大きく影響する。また、その帳票を用いてどのような業務フローにするかなど高い視座で考える起点となる</li></ol><p>帳票設計は、枯れた技術ではなく、今なおビジネスとシステムを繋ぐコア技術である。本ガイドラインがそうした帳票設計の品質向上の一助となれば幸いである。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責任を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記</li><li><strong>レビュアー</strong>: 井上拓、椎名祐介、藤野圭一、澁川喜規、宮崎将太</li></ul><div class="next-page-nav"><p>次のページ: <a href="./report_guidelines.html">帳票利用ガイドライン</a></p></div>',11)])])}const _=e(i,[["render",n]]);export{g as __pageData,_ as default};
